struct ModelBuilder {
  typedef Model Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_metadata(::flatbuffers::Offset<::flatbuffers::String> metadata) {
    fbb_.AddOffset(Model::VT_METADATA, metadata);
  }
  void add_guids(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> guids) {
    fbb_.AddOffset(Model::VT_GUIDS, guids);
  }
  void add_guids_items(::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> guids_items) {
    fbb_.AddOffset(Model::VT_GUIDS_ITEMS, guids_items);
  }
  void add_max_local_id(uint32_t max_local_id) {
    fbb_.AddElement<uint32_t>(Model::VT_MAX_LOCAL_ID, max_local_id, 0);
  }
  void add_local_ids(::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> local_ids) {
    fbb_.AddOffset(Model::VT_LOCAL_IDS, local_ids);
  }
  void add_categories(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> categories) {
    fbb_.AddOffset(Model::VT_CATEGORIES, categories);
  }
  void add_meshes(::flatbuffers::Offset<openskp::fragments_fb::Meshes> meshes) {
    fbb_.AddOffset(Model::VT_MESHES, meshes);
  }
  void add_attributes(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<openskp::fragments_fb::Attribute>>> attributes) {
    fbb_.AddOffset(Model::VT_ATTRIBUTES, attributes);
  }
  void add_relations(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<openskp::fragments_fb::Relation>>> relations) {
    fbb_.AddOffset(Model::VT_RELATIONS, relations);
  }
  void add_relations_items(::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> relations_items) {
    fbb_.AddOffset(Model::VT_RELATIONS_ITEMS, relations_items);
  }
  void add_guid(::flatbuffers::Offset<::flatbuffers::String> guid) {
    fbb_.AddOffset(Model::VT_GUID, guid);
  }
  void add_spatial_structure(::flatbuffers::Offset<openskp::fragments_fb::SpatialStructure> spatial_structure) {
    fbb_.AddOffset(Model::VT_SPATIAL_STRUCTURE, spatial_structure);
  }
  void add_unique_attributes(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> unique_attributes) {
    fbb_.AddOffset(Model::VT_UNIQUE_ATTRIBUTES, unique_attributes);
  }
  void add_relation_names(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> relation_names) {
    fbb_.AddOffset(Model::VT_RELATION_NAMES, relation_names);
  }
  void add_indexes(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<openskp::fragments_fb::ModelIndex>>> indexes) {
    fbb_.AddOffset(Model::VT_INDEXES, indexes);
  }
  explicit ModelBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<Model> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<Model>(end);
    fbb_.Required(o, Model::VT_GUIDS);
    fbb_.Required(o, Model::VT_GUIDS_ITEMS);
    fbb_.Required(o, Model::VT_LOCAL_IDS);
    fbb_.Required(o, Model::VT_CATEGORIES);
    fbb_.Required(o, Model::VT_MESHES);
    fbb_.Required(o, Model::VT_GUID);
    return o;
  }
};

inline ::flatbuffers::Offset<Model> CreateModel(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> metadata = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> guids = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> guids_items = 0,
    uint32_t max_local_id = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> local_ids = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> categories = 0,
    ::flatbuffers::Offset<openskp::fragments_fb::Meshes> meshes = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<openskp::fragments_fb::Attribute>>> attributes = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<openskp::fragments_fb::Relation>>> relations = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<int32_t>> relations_items = 0,
    ::flatbuffers::Offset<::flatbuffers::String> guid = 0,
    ::flatbuffers::Offset<openskp::fragments_fb::SpatialStructure> spatial_structure = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> unique_attributes = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> relation_names = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<openskp::fragments_fb::ModelIndex>>> indexes = 0) {
  ModelBuilder builder_(_fbb);
  builder_.add_indexes(indexes);
  builder_.add_relation_names(relation_names);
  builder_.add_unique_attributes(unique_attributes);
  builder_.add_spatial_structure(spatial_structure);
  builder_.add_guid(guid);
  builder_.add_relations_items(relations_items);
  builder_.add_relations(relations);
  builder_.add_attributes(attributes);
  builder_.add_meshes(meshes);
  builder_.add_categories(categories);
  builder_.add_local_ids(local_ids);
  builder_.add_max_local_id(max_local_id);
  builder_.add_guids_items(guids_items);
  builder_.add_guids(guids);
  builder_.add_metadata(metadata);
  return builder_.Finish();
}

inline ::flatbuffers::Offset<Model> CreateModelDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const char *metadata = nullptr,
    const std::vector<::flatbuffers::Offset<::flatbuffers::String>> *guids = nullptr,
    const std::vector<uint32_t> *guids_items = nullptr,
    uint32_t max_local_id = 0,
    const std::vector<uint32_t> *local_ids = nullptr,
    const std::vector<::flatbuffers::Offset<::flatbuffers::String>> *categories = nullptr,
    ::flatbuffers::Offset<openskp::fragments_fb::Meshes> meshes = 0,
    const std::vector<::flatbuffers::Offset<openskp::fragments_fb::Attribute>> *attributes = nullptr,
    const std::vector<::flatbuffers::Offset<openskp::fragments_fb::Relation>> *relations = nullptr,
    const std::vector<int32_t> *relations_items = nullptr,
    const char *guid = nullptr,
    ::flatbuffers::Offset<openskp::fragments_fb::SpatialStructure> spatial_structure = 0,
    const std::vector<::flatbuffers::Offset<::flatbuffers::String>> *unique_attributes = nullptr,
    const std::vector<::flatbuffers::Offset<::flatbuffers::String>> *relation_names = nullptr,
    const std::vector<::flatbuffers::Offset<openskp::fragments_fb::ModelIndex>> *indexes = nullptr) {
  auto metadata__ = metadata ? _fbb.CreateString(metadata) : 0;
  auto guids__ = guids ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*guids) : 0;
  auto guids_items__ = guids_items ? _fbb.CreateVector<uint32_t>(*guids_items) : 0;
  auto local_ids__ = local_ids ? _fbb.CreateVector<uint32_t>(*local_ids) : 0;
  auto categories__ = categories ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*categories) : 0;
  auto attributes__ = attributes ? _fbb.CreateVector<::flatbuffers::Offset<openskp::fragments_fb::Attribute>>(*attributes) : 0;
  auto relations__ = relations ? _fbb.CreateVector<::flatbuffers::Offset<openskp::fragments_fb::Relation>>(*relations) : 0;
  auto relations_items__ = relations_items ? _fbb.CreateVector<int32_t>(*relations_items) : 0;
  auto guid__ = guid ? _fbb.CreateString(guid) : 0;
  auto unique_attributes__ = unique_attributes ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*unique_attributes) : 0;
  auto relation_names__ = relation_names ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*relation_names) : 0;
  auto indexes__ = indexes ? _fbb.CreateVector<::flatbuffers::Offset<openskp::fragments_fb::ModelIndex>>(*indexes) : 0;
  return openskp::fragments_fb::CreateModel(
      _fbb,
      metadata__,
      guids__,
      guids_items__,
      max_local_id,
      local_ids__,
      categories__,
      meshes,
      attributes__,
      relations__,
      relations_items__,
      guid__,
      spatial_structure,
      unique_attributes__,
      relation_names__,
      indexes__);
}

